  'plans.faqWhatIsPlus': 'Что такое Chatyy One?',
  'plans.faqWhatIsPlusAnswer': 'Это премиум план Chatyy, который защищает все твои разговоры, фото и видео. С Chatyy One, даже если ты случайно что-то удалишь, можешь восстановить в течение 30 дней. Кроме того, ты получаешь 200 ГБ хранилища, One AI как личного помощника и можешь отправлять файлы до 100 МБ.',
  'plans.faqCancelAnswer': 'Твой план остается активным до конца оплаченного периода. После этого ты вернешься на бесплатный план. Твои фото и видео, превышающие 15 ГБ, будут храниться еще 30 дней, чтобы ты мог их скачать.',
  'plans.faqHowFamily': 'Как работает Pro план?',
  'plans.faqHowFamilyAnswer': 'Ты можешь добавить до 4 человек из своей семьи. Все делят 500 ГБ хранилища и получают все преимущества Chatyy One. У каждого есть свое личное пространство — никто не видит файлы других.',
  'plans.faqChangePlanAnswer': 'Да! Если ты сделаешь апгрейд с Plus на Pro, будет взиматься только пропорциональная разница. Если сделаешь даунгрейд, текущий план продолжится до конца периода.',
